steps.script:
window.__lmIndex = {
  page: () => document.querySelector('#LibraryMaintenanceConfigPage:not(.hide)'),
  status: () => ((__lmIndex.page() || document).querySelector('#LibraryMaintenanceDuplicatesStatus') || {}).textContent || '',
  api: async (method, path) => { const r = await fetch(ApiClient.getUrl(path), { method, headers: { Authorization: 'MediaBrowser Token="' + ApiClient.accessToken() + '"', Accept: 'application/json' } }); return { status: r.status, body: r.status === 204 ? null : await r.json() }; },
  requests: (part) => performance.getEntriesByType('resource').filter(e => e.name.indexOf(part) >= 0).length
};
return true;
